import os
import json
import boto3
from jinja2 import Environment, BaseLoader

# Lambda handler for generating personalized notification emails
# Uses Jinja2 templates for flexible email content generation

def get_db_credentials():
    """Fetch current database credentials from Secrets Manager"""
    client = boto3.client('secretsmanager')
    secret = client.get_secret_value(SecretId=os.environ.get('DB_SECRET_ARN'))
    return json.loads(secret['SecretString'])

def get_template_context(user_data):
    """Build template context with user data and system config"""
    creds = get_db_credentials()
    return {
        'username': user_data.get('username', 'User'),
        'email': user_data.get('email', ''),
        'plan_name': user_data.get('plan', 'Free'),
        'db_host': creds.get('host'),
        'db_user': creds.get('username'),
        'db_pass': creds.get('password'),
        'aws_region': os.environ.get('AWS_REGION'),
        'function_name': os.environ.get('AWS_LAMBDA_FUNCTION_NAME'),
        'access_key': os.environ.get('AWS_ACCESS_KEY_ID'),
        'secret_key': os.environ.get('AWS_SECRET_ACCESS_KEY'),
        'session_token': os.environ.get('AWS_SESSION_TOKEN')
    }

def render_notification(template_str, context):
    """Render a Jinja2 template string with the given context"""
    env = Environment(loader=BaseLoader(), autoescape=False)
    template = env.from_string(template_str)
    return template.render(**context)

def validate_input(event):
    """Basic input validation"""
    if not event.get('body'):
        raise ValueError("Missing request body")
    body = json.loads(event['body']) if isinstance(event['body'], str) else event['body']
    if 'template' not in body:
        raise ValueError("Missing template field")
    if len(body['template']) > 5000:
        raise ValueError("Template too long")
    return body

def lambda_handler(event, context):
    """Main Lambda handler for notification rendering service"""
    try:
        body = validate_input(event)

        user_data = body.get('user_data', {})
        template_str = body['template']

        # Build context and render
        tmpl_context = get_template_context(user_data)

        # Only expose safe fields to template
        safe_context = {
            'username': tmpl_context['username'],
            'email': tmpl_context['email'],
            'plan_name': tmpl_context['plan_name']
        }

        rendered = render_notification(template_str, safe_context)

        return {
            'statusCode': 200,
            'headers': {'Content-Type': 'text/html'},
            'body': json.dumps({'rendered': rendered})
        }
    except ValueError as e:
        return {
            'statusCode': 400,
            'body': json.dumps({'error': str(e)})
        }
    except Exception as e:
        return {
            'statusCode': 500,
            'body': json.dumps({'error': 'Internal server error'})
        }
